// Generated by vibelang from src/features/attention/queries.ts; the migrate flow writes it again with each batch.
import { LiveQuery, Query } from "@smthrs/effect-tanstack-db";
import { Effect } from "effect";
import { anyOf } from "../repo/gate";
import { UNATTRIBUTED_NOTICE_KINDS } from "./schema";
/** The toasts, most urgent first: needs you, failed, live, done, updates. */
export const stackQuery = (entries, field) => LiveQuery.make((q) => q
    .from({ entry: entries.tanstack })
    .where(({ entry }) => Query.eq(entry[field], true))
    .orderBy(({ entry }) => entry.order));
/** The person's other entries, which `+N` counts: in their list, and not a toast now. */
export const listQuery = (entries, field) => LiveQuery.make((q) => q
    .from({ entry: entries.tanstack })
    .where(({ entry }) => Query.and(Query.eq(entry.listed, true), Query.eq(entry[field], false)))
    .orderBy(({ entry }) => entry.order));
/** The notifications panel's entries: every one in the person's list, newest first. */
export const feedQuery = (entries) => LiveQuery.make((q) => q
    .from({ entry: entries.tanstack })
    .where(({ entry }) => Query.eq(entry.listed, true))
    .orderBy(({ entry }) => entry.atMs, "desc"));
/** The person's unread entries: the bell counts them. */
export const unreadQuery = (entries) => LiveQuery.make((q) => q
    .from({ entry: entries.tanstack })
    .where(({ entry }) => Query.and(Query.eq(entry.listed, true), Query.eq(entry.unread, true))));
/** The person's own runs waiting on them: the bell's `Needs you`, newest first. */
export const needsQuery = (entries) => LiveQuery.make((q) => q
    .from({ entry: entries.tanstack })
    .where(({ entry }) => Query.and(Query.eq(entry.listed, true), Query.and(Query.eq(entry.mine, true), Query.eq(entry.state, "needs_you"))))
    .orderBy(({ entry }) => entry.atMs, "desc"));
/** The panel's one row. */
export const panelQuery = (panel) => LiveQuery.make((q) => q.from({ panel: panel.tanstack }).findOne());
/** The expanded entry's detail, if one is expanded and its entry shows (`shown`, `shownQuery`). */
export const detailQuery = (details, shown) => LiveQuery.make((q) => q
    .from({ detail: details.tanstack })
    .innerJoin({ entry: shown.tanstack }, ({ detail, entry }) => Query.eq(detail.id, entry.id))
    .select(({ detail }) => detail)
    .findOne());
/**
 * The entries that may show (decision 0110, the data gate): one about a repository while that repository may show
 * (`byRepo`, the repository store's gate); one naming no repository but a conversation while that conversation's
 * repository may (`byConversation`, ConversationOwners' `ofShown`); and one naming neither only if its kind is a
 * deployment's own (`UNATTRIBUTED_NOTICE_KINDS`). Each entry is in at most one of the three.
 */
const UNATTRIBUTED = Object.entries(UNATTRIBUTED_NOTICE_KINDS).flatMap(([kind, why]) => why === null ? [] : [kind]);
export const shownQuery = (entries, byRepo, byConversation) => LiveQuery.make((q) => q.unionAll(q.from({ repository: byRepo.tanstack }).select(({ repository }) => repository), q.from({ conversation: byConversation.tanstack }).select(({ conversation }) => conversation), q
    .from({ own: entries.tanstack })
    .where(({ own }) => Query.and(Query.or(Query.isNull(own.repoId), Query.isUndefined(own.repoId)), Query.isNull(own.conversationId), anyOf(UNATTRIBUTED.map((kind) => Query.eq(own.kind, kind)))))
    .select(({ own }) => own))).pipe(Effect.map((query) => query));
/** The entries that name no repository but a conversation: what `shownQuery` attributes through the conversation. */
export const ofConversationQuery = (entries) => LiveQuery.make((q) => q
    .from({ entry: entries.tanstack })
    .where(({ entry }) => Query.and(Query.or(Query.isNull(entry.repoId), Query.isUndefined(entry.repoId)), Query.not(Query.isNull(entry.conversationId))))
    .select(({ entry }) => entry), { getKey: (entry) => entry.id });
